// Текст закона для сайта (подключается при открытии раздела)
(window.LAW_DATA = window.LAW_DATA || {})["fzofsb"] = {"items":[{"h":"Глава I. Основные положения"},{"n":"Статья 1","title":"Федеральная служба безопасности и её назначение","sub":[{"n":"1.1","text":"Федеральная служба безопасности (также - ФСБ) - единая централизованная система органов Федеральной службы безопасности, осуществляющая решение в пределах своих полномочий задач по обеспечению безопасности Российской Федерации."},{"n":"1.2","text":"Федеральная служба безопасности осуществляет деятельность по обеспечению безопасности Российской Федерации, защиты прав и свобод человека и гражданина от преступных и иных противоправных посягательств, а также координирует антитеррористическую и контрразведывательную деятельность правоохранительных органов."},{"n":"1.3","text":"Руководство деятельностью Федеральной службы безопасности осуществляется Правительством Российской Федерации. В пределах своей компетенции Федеральная служба безопасности координирует и контролирует деятельность всех правоохранительных органов и силовых структур в вопросах обеспечения безопасности Российской Федерации, в данном случае подразумевается, что все сотрудники правоохранительных органов и силовых структур обязаны подчиняться приказам и предписаниям сотрудников Федеральной службы безопасности"},{"n":"1.4","text":"Управление Федеральной службы безопасности по Нобарской области возглавляет начальник управления Федеральной службы безопасности по Нобарской области. Начальник управления Федеральной службы безопасности по Нобарской области формирует Устав Федеральной службы безопасности, который в свою очередь подлежит утверждению Правительством Российской Федерации."}]},{"n":"Статья 2","title":"Правовая основа деятельности федеральной службы безопасности","text":"Правовую основу деятельности Федеральной службы безопасности составляют Конституция Российской Федерации, настоящий Федеральный закон, другие федеральные законы, нормативные правовые акты Председателя Правительства Российской Федерации и иные нормативные правовые акты Российской Федерации, регулирующие деятельность федеральной службы безопасности."},{"n":"Статья 3","title":"Принципы деятельности федеральной службы безопасности","sub":[{"n":"1","text":"Законность;"},{"n":"2","text":"Уважение к соблюдению прав и свобод человека и гражданина;"},{"n":"3","text":"Гуманизм;"},{"n":"4","text":"Единство системы органов федеральной службы безопасности, а также централизация управления ими;"},{"n":"5","text":"Конспирация, сочетание гласных и негласных методов и средств деятельности."}],"text":"Деятельность Федеральной Службы безопасности осуществляется на основе следующих принципов:"},{"n":"Статья 4","title":"Правовая защита сотрудников органов федеральной службы безопасности","sub":[{"n":"4.1","text":"Сотрудники Федеральной службы безопасности при исполнении ими служебных обязанностей, являются представителями власти и находятся под защитой Государства. Законные требования сотрудников Федеральной службы безопасности обязательны для исполнения гражданами и должностными лицами. Никто не вправе вмешиваться в служебную деятельность Федеральной службы безопасности за исключением лиц, уполномоченных на то законами Российской Федерации."},{"n":"4.2","text":"Сотрудники Федеральной службы безопасности не несут ответственность за вред, причиненный лицам и организациям при применении оружия, специальных средств и физической силы, если применение оружия, специальных средств и физической силы осуществлялось в интересах соблюдения прав и свобод гражданина, а также в интересах обеспечения правовой безопасности."},{"n":"4.3","text":"Личные данные сотрудников Первой и Второй оперативно-следственных служб, Службы по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности являются государственной тайной в случаях, предусмотренных законодательством и могут передаваться в иные организации исключительно по решению начальника управления Федеральной службы безопасности по Нобарской области, по запросу прокурора или его заместителя, следователя в рамках следствия или по решению суда."},{"n":"4.4","text":"Любые процессуальные действия уголовного характера предусмотренные законом по отношению к сотруднику Федеральной службы безопасности при исполнении служебных обязанностей имеют права применять исключительно сотрудники Первой оперативно-следственных службы Федеральной службы безопасности либо сотрудники органов прокуратуры, Следственного комитета в соответствии с процессуальным законодательством. Порядок задержания сотрудников Федеральной службы безопасности иными органами регулируется статьёй 36 настоящего Федерального закона."},{"n":"4.5","text":"Сотрудники Федеральной службы безопасности при исполнении служебных обязанностей вправе использовать два режима идентификации:"},{"n":"•","text":"Режим «открытый» — сотрудник обязан предъявить служебное удостоверение с фотографией, ФИО, званием и должностью."},{"n":"•","text":"Режим «засекреченный» (конспиративный) — сотрудник обязан предъявить именной жетон с уникальным номером и назвать позывной. Сведения о личности такого сотрудника являются государственной тайной и не подлежат разглашению."},{"n":"","text":"Применение режима «засекреченный» допускается только при проведении оперативно-розыскных мероприятий, антитеррористических операций, внедрений и иных действий, предусматривающих сокрытие причастности к ФСБ. Решение о переходе в «засекреченный» режим принимает начальник управления ФСБ по Нобарской области или его заместитель."}]},{"n":"Статья 5","title":"Соблюдение прав и свобод человека и гражданина в деятельности федеральной службы безопасности","sub":[{"n":"5.1","text":"Действия (бездействие) сотрудника Федеральной службы безопасности, нарушающие права и законные интересы гражданина, государственного органа, общественного объединения, религиозной и иной организации, могут быть обжалованы в вышестоящий орган или вышестоящему должностному лицу, в органы прокуратуры либо в суд."},{"n":"5.2","text":"Сотрудники Федеральной службы безопасности при осуществлении в процессе своей деятельности, обязаны действовать исключительно в интересах Российской Федерации."},{"n":"5.3","text":"При выдвижении требований в отношении лиц, при обращении лица к сотруднику Федеральной службы безопасности, сотрудник Федеральной службы безопасности обязан назвать свои должность, звание, фамилию, предъявить по просьбе гражданина служебное удостоверения."},{"n":"5.4","text":"Сотрудники, находящиеся при исполнении обязанностей, предусматривающих сокрытие причастности к Федеральной службе безопасности, обязаны предоставить жетон и назвать позывной и номер жетона обратившемуся лицу только в случае, если сотрудник сам инициировал обращение к гражданину в рамках реализации своих полномочий, с целью максимального сокрытия причастности к Федеральной службе безопасности."},{"n":"5.5","text":"Образцы жетонов устанавливаются Председателем Правительства Российской Федерации."}]},{"h":"Глава II. Деятельность Федеральной службы безопасности"},{"n":"Статья 6","title":"Направление деятельности органов федеральной службы безопасности","sub":[{"n":"1","text":"Борьба с терроризмом;"},{"n":"2","text":"Борьба с экстремизмом;"},{"n":"3","text":"Борьба с коррупцией;"},{"n":"4","text":"Борьба с незаконным оборотом оружия и наркотрафиком;"},{"n":"5","text":"Борьба с организованной преступностью;"}],"text":"Деятельность органов Федеральной службы безопасности осуществляется по следующим основным направлениям:"},{"n":"Статья 7","title":"Борьба с терроризмом","sub":[{"n":"7.1","text":"Борьба с терроризмом — деятельность, осуществляемая Федеральной службой безопасности по выявлению, предупреждению, пресечению, раскрытию и расследованию дел, связанных с совершением террористических актов или террористическими организациями."},{"n":"7.2","text":"Борьба с терроризмом предполагает проведение следственных, розыскных и иных оперативных мероприятий. Проведение мероприятий, ограничивающих права граждан на территории Российской Федерации, допускается только на основании ордера от Верховного Суда."},{"n":"7.3","text":"В неотложных случаях, когда промедление может привести к совершению террористического акта, либо имеются данные, позволяющие предполагать, что на частной территории совершается или совершен террористический акт, или осуществляется преследование лица, подозреваемого в причастности к его совершению, сотрудники Управления «А» Федеральной службы безопасности имеют право беспрепятственно проникать на частную собственность. В случае применения данного права сотрудники обязаны уведомить Директора Федеральной службы безопасности не позднее чем в течение часа."}]},{"n":"Статья 8","title":"Борьба с экстремизмом","sub":[{"n":"8.1","text":"Борьба с экстремизмом — деятельность, осуществляемая Федеральной службой безопасности по выявлению, предупреждению, пресечению, раскрытию и расследованию дел, связанных с деятельностью, направленной на насилие, разжигание межнациональной или межрелигиозной вражды, подрыв конституционного строя либо иные действия, представляющие угрозу национальной безопасности."},{"n":"8.2","text":"Федеральная служба безопасности имеет право собирать информацию о потенциальных экстремистских организациях, их членах и деятельности, включая мониторинг всех информационных источников, телефонных разговоров и иных форм коммуникации."}]},{"n":"Статья 9","title":"Борьба с коррупцией","text":"Борьба с коррупцией — деятельность, осуществляемая Федеральной службой безопасности по выявлению, предупреждению, пресечению, раскрытию и расследованию дел, связанных с превышением должностных полномочий государственными служащими, получением ими лично либо через посредников взятки в виде денег, ценных бумаг, иного имущества, а также в виде незаконно оказанных услуг имущественного характера или предоставления иных имущественных прав за совершение действий (бездействия) в пользу взяткодателя или представляемых им лиц, если такие действия входят в служебные полномочия должностного лица либо оно может способствовать их совершению по своей должности, а также за общее покровительство или попустительство по службе."},{"n":"Статья 10","title":"Борьба с преступностью","sub":[{"n":"10.1","text":"Борьба с незаконным оборотом оружия и наркотрафиком — деятельность, осуществляемая Федеральной службой безопасности по выявлению, предупреждению, пресечению, раскрытию, расследованию дел и мониторингу наркотрафикантов, их сетей и криминальных организаций, занимающихся незаконным оборотом наркотиков, оружия и иных видов контрабанды."},{"n":"10.2","text":"Борьба с организованной преступностью — деятельность, осуществляемая Федеральной службой безопасности в рамках оперативно-розыскных мероприятий по выявлению, предупреждению, пресечению и раскрытию организованных преступных структур, преступлений, отнесённых действующим законодательством к компетенции ФСБ, а также по борьбе с незаконными вооружёнными формированиями, преступными группами и отдельными лицами, представляющими угрозу безопасности Российской Федерации."}]},{"h":"Глава III. Полномочия органов Федеральной службы безопасности"},{"n":"Статья 11","title":"Обязанности органов федеральной службы безопасности","sub":[{"n":"11.1","text":"Органы федеральной службы безопасности обязаны:"},{"n":"1","text":"информировать Председателя Правительства Российской Федерации и по его поручениям федеральные органы государственной власти Российской Федерации об угрозах безопасности Российской Федерации;​"},{"n":"2","text":"выявлять, предупреждать, пресекать и раскрывать преступления, дознание и предварительное следствие в соответствии с уголовно-процессуальным законодательством;​"},{"n":"3","text":"выявлять, предупреждать и пресекать административные правонарушения в соответствии с процессуальным и административным законодательством;​"},{"n":"4","text":"разрабатывать и осуществлять во взаимодействии с другими государственными органами меры по борьбе с коррупцией, незаконным оборотом оружия и наркотических средств, деятельностью незаконных вооруженных формирований;​"},{"n":"5","text":"выявлять, предупреждать, пресекать, раскрывать и расследовать готовящиеся, совершающиеся и совершенные террористические акты, а также добывать информацию о событиях или действиях, создающих угрозу терроризма;​"},{"n":"6","text":"реагировать на похищения граждан и иных лиц, предпринимать меры по предотвращению, прекращению актов похищения;​"},{"n":"7","text":"осуществлять розыск лиц, совершивших преступления или подозреваемых и обвиняемых в их совершении; лиц, скрывшихся от органов дознания, следствия или суда;​"},{"n":"8","text":"участвовать в обеспечении режима военного положения и режима чрезвычайного положения в случае их введения на территории Российской Федерации или в отдельных ее местностях.​"},{"n":"11.2","text":"Иные обязанности возлагаются на Федеральную службу безопасности в соответствии с законодательством Российской Федерации, нормативными правовыми актами Председателя Правительства Российской Федерации."},{"n":"11.3","text":"Порядок выполнения возложенных на Федеральную службу безопасности обязанностей, если он не является предметом регулирования федеральных законов, нормативных правовых актов Председателя Правительства Российской Федерации или нормативных правовых актов Правительства Российской Федерации, определяется Председателем Правительства Российской Федерации путем издания нормативного правового акта."}]},{"n":"Статья 12","title":"Права органов федеральной службы безопасности","sub":[{"n":"12.1","text":"Органы федеральной службы безопасности имеют право:"},{"n":"1)","text":"устанавливать на конфиденциальной основе отношения сотрудничества с лицами, давшими на то согласие;​","lvl":1},{"n":"2)","text":"осуществлять дознание и предварительное следствие в соответствии с уголовно-процессуальным законодательством;​","lvl":1},{"n":"3)","text":"составлять протоколы об административных правонарушениях, выносить определения и постановления по делам об административных правонарушениях, назначать административные наказания по делам об административных правонарушениях, вносить представления об устранении причин и условий, способствовавших совершению административных правонарушений, и осуществлять иные полномочия по делам об административных правонарушениях в соответствии с административным и процессуальным законодательством;​","lvl":1},{"n":"4)","text":"временно ограничивать или запрещать передвижение граждан и транспортных средств по отдельным участкам местности (на отдельных объектах), обязывать граждан оставаться там или покинуть эти участки (объекты) в целях защиты жизни, здоровья и имущества граждан, проведения неотложных следственных действий, оперативно-розыскных и антитеррористических мероприятий;​","lvl":1},{"n":"5)","text":"проверять у лиц документы, удостоверяющие их личность;​","lvl":1},{"n":"6)","text":"ознакамливаться с необходимыми документами и материалами, в том числе с персональными данными граждан, имеющими отношение к расследованию уголовных дел, производству по делам об административных правонарушениях;​","lvl":1},{"n":"7)","text":"проводить криминалистические и другие экспертизы и исследования;​","lvl":1},{"n":"8)","text":"осуществлять меры по обеспечению собственной безопасности;​","lvl":1},{"n":"9)","text":"производить задержание, обыск и другие действия согласно процессуальному законодательству;​","lvl":1},{"n":"10)","text":"применять боевую технику, оружие, специальные средства, принятые на вооружение органов федеральной службы безопасности, физическую силу, а также разрешать сотрудникам органов федеральной службы безопасности хранение и ношение табельного оружия и специальных средств;​","lvl":1},{"n":"11)","text":"применять летальное огнестрельное оружие в случаях возникновения угрозы жизни гражданским и иным лицам или в случаях угрозы риска сокрытия подозреваемого;​","lvl":1},{"n":"12)","text":"разрешать сотрудникам органов федеральной службы безопасности первой и второй оперативно-следственной служб Федеральной службы безопасности использовать форму одежды и транспортные средства без знаков принадлежности к Федеральной службе безопасности в целях ведения наблюдения, переговоров и задержания террористов, экстремистов, особо опасных преступников и проведения специальных операций.","lvl":1},{"n":"13)","text":"изымать у граждан и должностных лиц вещи, изъятые из гражданского оборота или ограниченно оборотоспособные, находящиеся у них без специального разрешения;​","lvl":1},{"n":"14)","text":"выдвигать обязательные к исполнению законные требования в порядке, предусмотренном законодательством.​","lvl":1},{"n":"15)","text":"В случае отсутствия жетона, при сокрытии личности - предъявлять служебное удостоверение с закрытой для общества информацией (Фотография, ФИО сотрудника, его звание и должность)","lvl":1},{"n":"12.2","text":"Иные права предоставляются Федеральной службе безопасности в соответствии с законодательством Российской Федерации, нормативными правовыми актами Председателя Правительства Российской Федерации."},{"n":"12.3","text":"Права Федеральной службы безопасности реализуются должностными лицами Федеральной службы безопасности в пределах их компетенции, установленной законодательством Российской Федерации, нормативными правовыми актами Председателя Правительства Российской Федерации."}]},{"n":"Статья 13","title":"Полномочия начальника управления Федеральной службы безопасности по Нобарской области","sub":[{"n":"1)","text":"осуществляет руководство управлением Федеральной службой безопасности;​","lvl":1},{"n":"2)","text":"осуществляет руководство всеми правоохранительными, силовыми и иными государственными организациями в случае объявления чрезвычайного положения;​","lvl":1},{"n":"3)","text":"осуществляет руководство всеми правоохранительными структурами в случае объявления военного положения, проведения специальной операции (рейд, освобождение заложников и подобные);​","lvl":1},{"n":"4)","text":"подает от имени Федеральной службы безопасности исковые заявления в Верховный суд Российской Федерации;​","lvl":1},{"n":"5)","text":"отстраняет сотрудника государственной организации по основаниям и в порядке, предусмотренным трудовым законодательством;​","lvl":1},{"n":"6)","text":"осуществляет иные полномочия в соответствии с законодательством.​","lvl":1}],"text":"Начальник управления Федеральной службой безопасности по Нобарской области:"},{"h":"Глава IV. Силы и средства органов Федеральной службы безопасности"},{"n":"Статья 14","title":"Сотрудники органов федеральной службы безопасности","sub":[{"n":"14.1","text":"Сотрудники Федеральной службы безопасности обязаны соблюдать законы Российской Федерации и действовать в соответствии с ними. Сотрудники Федеральной службы безопасности обязаны знать и соблюдать нормативные правовые акты, составляющие правовую основу деятельности Федеральной службы безопасности."},{"n":"14.2","text":"Сотрудники Федеральной службы безопасности обязаны пройти обязательную военную выучку и иметь документ (также — военный билет), подтверждающий прохождение военной подготовки. Осмотр и проверка наличия документов может быть проведена индивидуально либо как часть общей проверки, назначенной прокуратурой Российской Федерации."}]},{"n":"Статья 15","title":"Служба в органах федеральной службы безопасности","sub":[{"n":"15.1","text":"Сотрудники органов федеральной службы безопасности руководствуются в своей служебной деятельности федеральными законами и не могут быть связаны решениями политических партий, общественных объединений и иных организаций."},{"n":"15.2","text":"Порядок прохождения службы в органах федеральной службы безопасности определяется также законодательством о государственной службе."}]},{"n":"Статья 16","title":"Лица, оказывающие содействие органам Федеральной службы безопасности, их права и обязанности","sub":[{"n":"16.1","text":"Лица, оказывающие содействие органам Федеральной службы безопасности, имеют право:"},{"n":"1)","text":"заключить контракт с органами Федеральной службы безопасности о конфиденциальном сотрудничестве;​","lvl":1},{"n":"2)","text":"получать от сотрудников органов Федеральной службы безопасности разъяснения своих задач, обязанностей и прав;​","lvl":1},{"n":"3)","text":"использовать в целях конспирации документы, зашифровывающие личность;​","lvl":1},{"n":"4)","text":"получать вознаграждение.​","lvl":1},{"n":"16.2","text":"Лица, оказывающие содействие органам Федеральной службы безопасности, обязаны:"},{"n":"1)","text":"соблюдать условия заключаемого с органами Федеральной службы безопасности контракта или договоренности о сотрудничестве;​","lvl":1},{"n":"2)","text":"выполнять поручения органов Федеральной службы безопасности, направленные на осуществление возложенных на них обязанностей;​","lvl":1},{"n":"3)","text":"не допускать умышленного предоставления необъективной, неполной, ложной или клеветнической информации;​","lvl":1},{"n":"4)","text":"не разглашать сведения, составляющие государственную тайну, и иные сведения, ставшие им известными в процессе оказания содействия органам Федеральной службы безопасности;​","lvl":1},{"n":"5)","text":"подчиняться любым приказам, отдаваемым ответственными сотрудниками Федеральной службы безопасности во время действия контракта содействия.​","lvl":1}]},{"h":"Глава V. Структура Федеральной службы безопасности"},{"n":"Статья 17","title":"Службы Федеральной службы безопасности","sub":[{"n":"17.1","text":"Структура Федеральной службы безопасности закреплена настоящим законом."},{"n":"17.2","text":"Федеральная служба безопасности состоит из следующих служб:"},{"n":"1)","text":"Первая служба - Первая оперативно-следственная служба (Управление «М» ФСБ);​","lvl":1},{"n":"2)","text":"Вторая служба - Вторая оперативно-следственная служба (Управление «К» ФСБ);​","lvl":1},{"n":"3)","text":"Третья служба - Третья служба по защите конституционного строя и борьбе с экстремизмом и терроризмом (Управление «А» ФСБ);​","lvl":1},{"n":"4)","text":"Четвертая служба - Четвертая служба организационно-кадровой работы (Управление «О» ФСБ);​","lvl":1},{"n":"5)","text":"Пятая служба - Пятая служба прикомандированных сотрудников (АПС ФСБ).​","lvl":1}]},{"n":"Статья 18","title":"Первая оперативно-следственная служба Федеральной службы безопасности и ее задачи","sub":[{"n":"18.1","text":"Первая служба - Первая оперативно-следственная служба Федеральной службы безопасности (Управление «М» ФСБ) - обособленное структурное подразделение прямого подчинения Начальнику управления Федеральной службы безопасности по Нобарской области, осуществляющее следственную и инспекторскую деятельность в структуре Федеральной службы безопасности."},{"n":"18.2","text":"Основными задачи Первой оперативно-следственной службы Федеральной службы безопасности являются:"},{"n":"1)","text":"обеспечение законности при обработке сообщений о преступлениях, возбуждении уголовных дел, производстве предварительного расследования, а также защита прав и свобод человека и гражданина;​","lvl":1},{"n":"2)","text":"оперативное и качественное расследование преступлений;​","lvl":1},{"n":"3)","text":"осуществление инспекций правоохранительных органов;​","lvl":1},{"n":"4)","text":"осуществление антикоррупционных мероприятий и профилактика коррупции.​","lvl":1}]},{"n":"Статья 19","title":"Сотрудники Первой оперативно-следственной службы Федеральной службы безопасности","text":"Сотрудники Первой оперативно-следственной службы Федеральной службы безопасности при проведении инспекционных мероприятий обязаны находиться в служебной форме без сокрытия лица и удостоверений."},{"n":"Статья 20","title":"Полномочия сотрудников Первой оперативно-следственной службы Федеральной службы безопасности","sub":[{"n":"20.1","text":"Сотрудники Первой оперативно-следственной службы Федеральной службы безопасности уполномочены проводить розыскные мероприятия по выявлению, предупреждению, пресечению и раскрытию деятельности незаконных вооруженных формирований и преступных групп, борьбе с коррупцией и преступлениями совершенными сотрудниками правоохранительных органов в соответствии с уголовно-процессуальным законодательством."},{"n":"20.2","text":"Полномочия сотрудников Первой оперативно-следственной службы Федеральной службы безопасности:"},{"n":"1)","text":"осуществлять следствие по делам о преступлениях, отнесенных законодательством к ведению Федеральной службы безопасности;​","lvl":1},{"n":"2)","text":"осуществлять криминалистические и другие экспертизы и исследования;​","lvl":1},{"n":"3)","text":"осуществлять инспекции правоохранительным органам;​","lvl":1},{"n":"4)","text":"возбуждать уголовные дела в отношении граждан в случае совершения ими преступлений в рамках подследственности органов Федеральной службы безопасности, при процессуальном руководстве прокурора;​","lvl":1},{"n":"5)","text":"осуществлять иные полномочия, установленные законодательством Российской Федерации.​","lvl":1},{"n":"20.3","text":"При проведении инспекции сотрудники Управления «М» Федеральной службы безопасности имеют право, если иное не предусмотрено настоящим законом:"},{"n":"1)","text":"проверить сотрудников инспектируемой организации на знание внутреннего устава организации;​","lvl":1},{"n":"2)","text":"проверить сотрудников инспектируемой организации на знание общей документации относящейся к деятельности организации;​","lvl":1},{"n":"3)","text":"проверить сотрудников инспектируемой организации на профессиональную пригодность и моральные качества;​","lvl":1},{"n":"4)","text":"выделить и подробно расписать о проблемах инспектируемой организации с последующей передачей информации руководителю организации;​","lvl":1},{"n":"5)","text":"проверить сотрудников инспектируемой организации на наличие необходимых документов для несения службы.​","lvl":1}]},{"n":"Статья 21","title":"Полномочия Начальника Первой оперативно-следственной службы Федеральной службы безопасности","sub":[{"n":"21.1","text":"Начальник Первой оперативно-следственной службы Федеральной службы безопасности является заместителем Начальника управления Федеральной службы безопасности по Нобарской области."},{"n":"21.2","text":"Начальник Первой оперативно-следственной службы Федеральной службы безопасности вправе:"},{"n":"1)","text":"отстранить сотрудника государственной организации по основаниям и в порядке, предусмотренным трудовым законодательством, с имеющимися на то доказательствами посредством выпуска постановления (за исключением руководителей и заместителей руководителей правоохранительного органа, объявление им взыскания допускается исключительно в судебном порядке). Каждое постановление об объявлении взыскания подлежит официальному опубликованию;​","lvl":1},{"n":"2)","text":"объявить дисциплинарное взыскание всему личному составу организации или конкретному сотруднику правоохранительного органа по результатам инспекции посредством выпуска постановления с последующей передачей доказательств руководителю организации нарушителя.​","lvl":1}]},{"n":"Статья 22","title":"Инспекции, проводимые Первой оперативно-следственной службой Федеральной службы безопасности","sub":[{"n":"22.1","text":"Начальник Первой оперативно-следственной службы назначает инспекцию, определяет дату и время, порядок проведения инспекции. Инспекция проводится в рабочее время правоохранительного органа, который инспектируется. Не проводится инспекции Первой оперативно-следственной службой в отношении судебных органов, органов прокуратуры, Следственного Комитета Российской Федерации, за исключением случаев, предусмотренных частью второй настоящей статьи."},{"n":"22.2","text":"Первая оперативно-следственная служба обязана проводить инспекции или иные следственные мероприятия назначенные им решением Верховного суда Российской Федерации."},{"n":"22.3","text":"Любые решения инспекционной группы проверяемая организация может обжаловать только посредством составления искового заявления о признании нелегитимными итоги инспекции либо посредством обращения в органы прокуратуры. Отмена действий итогов инспекции осуществляет Верховный суд Российской Федерации."}]},{"n":"Статья 23","title":"Вторая оперативно-следственная служба Федеральной службы безопасности и ее задачи","sub":[{"n":"23.1","text":"Вторая оперативно-следственная служба Федеральной службы безопасности (Управление «К» ФСБ России) - структурное подразделение, осуществляющее следственную деятельность в структуре Федеральной службы безопасности, а также контроль за оборотом наркотиков, оружия и контрабанды."},{"n":"23.2","text":"Основными задачами Второй оперативно-следственной службы Федеральной службы безопасности являются:"},{"n":"1)","text":"проведение контрольных закупок оружия и наркотических веществ;​","lvl":1},{"n":"2)","text":"осуществление рейдов на места хранения наркотических вещество, места нелегального хранения оружия;​","lvl":1},{"n":"3)","text":"осуществление контроля за оборотом наркосодержащих препаратов;​","lvl":1},{"n":"4)","text":"обеспечение законности при обработке сообщений о преступлениях, возбуждении уголовных дел, производстве предварительного расследования, а также защита прав и свобод человека и гражданина;​","lvl":1},{"n":"5)","text":"оперативное и качественное расследование преступлений.​","lvl":1}]},{"n":"Статья 24","title":"Сотрудники Второй оперативно-следственной службы Федеральной службы безопасности","text":"Сотрудники Второй оперативно-следственной службы Федеральной службы безопасности при проведении контрольных закупок, внедрений и прочих мероприятий, предполагающих сокрытие причастности к Федеральной службы безопасности, имеют право на осуществление своей деятельности и проведение процессуальных действия вне служебной формы, однако удостоверение обязано присутствовать при сотруднике. Каждая операция, предполагающая сокрытие причастности к Федеральной службы безопасности санкционируется в соответствии с уголовно-процессуальным законодательством."},{"n":"Статья 25","title":"Полномочия сотрудников Второй оперативно-следственной службы Федеральной службы безопасности","sub":[{"n":"25.1","text":"Сотрудники Второй оперативно-следственной службы Федеральной службы безопасности уполномочены проводить розыскные мероприятия по выявлению, предупреждению, пресечению и раскрытию организованной преступности, деятельности незаконных вооруженных формирований и преступных групп."},{"n":"25.2","text":"Полномочия сотрудников Второй оперативно-следственной службы Федеральной службы безопасности:"},{"n":"1)","text":"осуществлять внедрения в преступные группировки;​","lvl":1},{"n":"2)","text":"осуществлять следствие в соответствии с уголовно-процессуальным законодательством;​","lvl":1},{"n":"3)","text":"осуществлять иные полномочия, установленные законодательством Российской Федерации.​","lvl":1}]},{"n":"Статья 26","title":"Третья служба по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности и ее задачи","sub":[{"n":"26.1","text":"Третья служба по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности (Управление «А» ФСБ) - основное силовое структурное подразделение Федеральной службы безопасности, осуществляющее деятельность по защите конституционного строя, по борьбе с терроризмом и экстремизмом."},{"n":"26.2","text":"Основными задачами Третьей службы по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности являются:"},{"n":"1)","text":"организация и проведение антитеррористических операций, включая пресечение террористических актов и нейтрализацию террористических угроз;​","lvl":1},{"n":"2)","text":"силовое сопровождение оперативно-розыскных и следственных мероприятий, проводимых органами Федеральной службы безопасности;​","lvl":1},{"n":"3)","text":"обеспечение безопасности защищаемых лиц, включая свидетелей, потерпевших, судей, должностных лиц государственных органов;​","lvl":1},{"n":"4)","text":"ведение переговоров при захвате заложников, разработка и проведение операций по их освобождению;​","lvl":1},{"n":"5)","text":"задержание, арест или ликвидация террористов, членов незаконных вооруженных формирований и особо опасных преступников;​","lvl":1},{"n":"6)","text":"документирование кризисных ситуаций (фото-видеофиксация, сбор вещественных доказательств) для последующего расследования;​","lvl":1},{"n":"7)","text":"координация и оперативное руководство совместными действиями силовых структур при проведении антитеррористических и специальных операций.​","lvl":1}]},{"n":"Статья 27","title":"Сотрудники Третьей службы по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности","sub":[{"n":"27.1","text":"Сотрудники Третьей службы по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности уполномочены оказывать содействие всем правоохранительным органам в обеспечении борьбы с преступностью и организованной преступностью."},{"n":"27.2","text":"Сотрудники Третьей службы по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности осуществляют оперативное руководство и контроль проведении совместных силовых операций с другими силовыми структурами в рамках своей компетенции.В случае если не определено иное вышестоящим руководством."},{"n":"27.3","text":"В случаях, требующих немедленного реагирования (похищения людей, террористические акты, массовые беспорядки), сотрудники Третьей службы по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности вправе брать на себя координацию действий всех задействованных силовых подразделений на территории проведения операции.В случае если не определено иное вышестоящим руководством."},{"n":"27.4","text":"При проведении операций в зонах повышенной криминогенной опасности (например, в районах активной деятельности бандформирований) сотрудники Третьей службы по защите конституционного строя и борьбе с экстремизмом и терроризмом Федеральной службы безопасности обладают приоритетом в принятии решений, касающихся тактики проведения операции, применения специальных средств, иных средств и вооружения. В случае если не определено иное вышестоящим руководством."}]},{"n":"Статья 28","title":"Четвертая служба организационно-кадровой работы Федеральной службы безопасности","text":"Четвертая служба организационно-кадровой работы Федеральной службы безопасности (Управление «О» ФСБ) - служба Федеральной службы безопасности, которая отвечает за все внутренние кадровые потребности Федеральной службы безопасности и организацию деятельности Академии Федеральной службы безопасности для обучения новых оперативников ФСБ."},{"n":"Статья 29","title":"Пятая служба прикомандированных сотрудников Федеральной службы безопасности и ее задачи","sub":[{"n":"29.1","text":"Пятая служба прикомандированных сотрудников Федеральной службы безопасности - служба Федеральной службы безопасности, отвечающая за прикомандирование сотрудников по контракту к силовым государственным организациям, перечень которых определяется частью второй настоящей статьи с целью осуществления оперативно-розыскной деятельности, контроля специального оборудования, выполнения особых поручений, обеспечения законности."},{"n":"29.2","text":"Пятая служба прикомандированных сотрудников Федеральной службы безопасности осуществляет прикомандирование в органы внутренних дел, войска национальной гвардии, Вооруженные Силы Российской Федерации, органы уголовно-исполнительной системы, государственные медицинские организации, организации средств массовой информации."},{"n":"29.3","text":"Основными задачами Пятой службы прикомандированных сотрудников Федеральной службы безопасности являются:"},{"n":"1)","text":"обеспечение законности при исполнении служебных обязанностей сотрудниками организаций, к которым осуществляется внедрение;​","lvl":1},{"n":"2)","text":"осуществление наблюдения за деятельностью сотрудников организаций, к которым осуществляется внедрение;​","lvl":1},{"n":"3)","text":"отслеживание эффективности и уровня организованности организации, к которой осуществляется внедрение.​","lvl":1}]},{"n":"Статья 30","title":"Сотрудники Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности","sub":[{"n":"30.1","text":"Прикомандирование (выполнение сотрудником деятельности в другой организации с сохранением трудовых отношений с первоначальным работодателем) производится путем издания приказа Начальником Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности. Руководство государственной организации, к которой осуществляется прикомандирование, обязаны принять соответствующих прикомандированных сотрудников. В государственных организациях, предусматривающих наличие специальные или воинские звания, классные чины, прикомандированному сотруднику предоставляется специальное или воинское звание, классный чин соответствующий званию сотрудника в органах Федеральной службы безопасности. В иных государственных организациях сотруднику предоставляется должность заместителя начальника отдела организации."},{"n":"30.2","text":"В государственной организации может находиться (осуществлять деятельность) не более одного прикомандированного сотрудника."},{"n":"30.3","text":"Прикомандированные сотрудники обязаны соблюдать требования нормативных правовых актов регламентирующих деятельность государственной структуры, организации к которой они прикомандированы, соблюдая при этом нормативные правовые акты, регламентирующие деятельность сотрудников Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности."}]},{"n":"Статья 31","title":"Полномочия сотрудников Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности","sub":[{"n":"31.1","text":"Сотрудники Пятой службы прикомандированных сотрудников Федеральной службы безопасности уполномочены проводить розыскные мероприятия по выявлению, предупреждению, пресечению и раскрытию незаконной деятельности в государственных организаций, осуществлять наблюдение, регистрирование случаев и происшествий."},{"n":"31.2","text":"Полномочия сотрудников Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности:"},{"n":"1)","text":"осуществлять все полномочия сотрудника государственной организации, к которой он прикомандирован;​","lvl":1},{"n":"2)","text":"иметь заключенный контракт с прикомандированной государственной организацией, являться сотрудником государственной организации, к которой он прикомандирован, оставаясь на службе в органах Федеральной службы безопасности;​","lvl":1},{"n":"3)","text":"в случае выявления нарушения сотрудниками государственной организации, к которой осуществляется прикомандирование, составлять рапорт в Первую оперативно-следственную службу Федеральной службы безопасности или в органы Следственного Комитета;​","lvl":1},{"n":"4)","text":"составлять отчет о деятельности государственной организации, к которой осуществляется прикомандирование, на имя Начальника Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности;​","lvl":1},{"n":"5)","text":"запрашивать и получать необходимую информацию от любых подразделений государственной организации, к которой осуществляется прикомандирование;​","lvl":1},{"n":"6)","text":"осуществлять иные полномочия, установленные законодательством Российской Федерации.​","lvl":1},{"n":"31.2","text":"Сотрудник Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности не может занимать должности, связанные с непосредственным управлением государственной организации, к которой осуществляется прикомандирование."},{"n":"31.3","text":"Сотрудник Пятой службы прикомандированных сотрудников службы Федеральной службы безопасности за нарушение нормативных правовых актов, за исключением локальных, регламентирующих деятельность государственной организации, к которой осуществляется прикомандирование может быть отозван из государственной организации, к которой осуществляется прикомандирование с применением соответствующих дисциплинарных взысканий."}]},{"h":"Глава VI. Контроль и надзор за деятельностью Федеральной службы безопасности"},{"n":"Статья 32","title":"Судебный, прокурорский надзор","sub":[{"n":"32.1","text":"Судебный надзор за деятельностью Федеральной службы безопасности осуществляется в соответствии с федеральными законами."},{"n":"32.2","text":"Надзор за исполнением Федеральной службой безопасности законов осуществляют органы прокуратуры с полномочиями, предоставленными федеральным законодательством."}]},{"n":"Статья 33","title":"Государственный контроль","text":"Государственный контроль за деятельностью Федеральной службы безопасности осуществляет Председатель Правительства Российской Федерации в пределах полномочий, определяемых Конституцией Российской Федерации, федеральными законами."},{"n":"Статья 34","title":"Обжалование действий сотрудников Федеральной службы безопасности","text":"Все расследования в отношении Федеральной службы безопасности инициированные по обращение в прокуратуру или исковому заявлению проводятся исключительно сотрудниками Следственного комитета в соответствии с уголовно-процессуальным законодательством."},{"h":"Глава VII. Особенности взаимодействия с органами внутренних дел и привлечения сотрудников Федеральной службы безопасности к административной ответственности"},{"n":"Статья 35","title":"Привлечение сотрудников Федеральной службы безопасности к административной ответственности","sub":[{"n":"35.1","text":"Привлечение сотрудников Федеральной службы безопасности к административной ответственности, в том числе за нарушения Правил дорожного движения, осуществляется дифференцированно в зависимости от режима идентификации сотрудника:"},{"n":"а)","text":"В режиме «открытый» (сотрудник предъявил служебное удостоверение с фотографией, ФИО, званием и должностью) — сотрудники ГИБДД и иных уполномоченных органов вправе самостоятельно составлять протоколы, выносить постановления и назначать административные наказания на общих основаниях. Копия постановления в течение 24 часов направляется в управление ФСБ по Нобарской области.","lvl":1},{"n":"б)","text":"В режиме «засекреченный» (конспиративный) (сотрудник предъявил именной жетон с номером и назвал позывной) — сотрудники ГИБДД и иных уполномоченных органов не вправе составлять протоколы, задерживать такого сотрудника или применять к нему меры административного принуждения.","lvl":1},{"n":"35.2","text":"Привлечение к ответственности сотрудника, находящегося в режиме «засекреченный», осуществляется исключительно в следующем порядке:"},{"n":"1","text":"Подача искового заявления в суд (в порядке административного или гражданского судопроизводства) с указанием номера жетона, позывного, времени, места и обстоятельств нарушения; либо"},{"n":"2","text":"Направление официальной жалобы на имя начальника управления Федеральной службы безопасности по Нобарской области по месту совершения предполагаемого нарушения."},{"n":"35.3","text":"Жалоба в управление ФСБ по Нобарской области подаётся в письменной форме и должна содержать:"},{"n":"•","text":"номер жетона сотрудника;"},{"n":"•","text":"позывной;"},{"n":"•","text":"описание обстоятельств;"},{"n":"•","text":"при наличии — фото-, видеодоказательства или показания свидетелей."},{"n":"35.4","text":"Начальник управления ФСБ по Нобарской области обязан рассмотреть жалобу в срок не более 10 рабочих дней и принять одно из решений:"},{"n":"•","text":"применить к сотруднику меры дисциплинарного воздействия (вплоть до увольнения);"},{"n":"•","text":"передать материалы в Первую оперативно-следственную службу (Управление «М») для служебной проверки;"},{"n":"•","text":"отказать в удовлетворении жалобы с письменным обоснованием."},{"n":"35.5","text":"В случае отказа начальника управления ФСБ по Нобарской области в удовлетворении жалобы заявитель вправе обратиться в суд. При этом сведения о личности сотрудника в «засекреченном» режиме предоставляются суду в закрытом режиме."},{"n":"35.6","text":"Сотрудники ГИБДД и иных контролирующих органов не несут ответственности за добросовестное исполнение требований настоящей статьи."}]},{"n":"Статья 36","title":"Задержание сотрудников Федеральной службы безопасности и производство процессуальных действий","sub":[{"n":"36.1","text":"Задержание сотрудника Федеральной службы безопасности по подозрению в совершении административного правонарушения или преступления, а также производство любых процессуальных действий (обыск, выемка, личный досмотр, наложение ареста на имущество, избрание меры пресечения и иные действия, предусмотренные уголовно-процессуальным и административным законодательством) не допускается сотрудниками органов внутренних дел (полиции), войск национальной гвардии, органов уголовно-исполнительной системы, МЧС, военнослужащими и сотрудниками иных государственных органов, за исключением случаев, предусмотренных частями 36.2 и 36.3 настоящей статьи."},{"n":"36.2","text":"Процессуальные действия по отношению к сотруднику Федеральной службы безопасности, включая задержание, производство обыска, выемки, допроса, предъявления обвинения и избрания меры пресечения, осуществляются исключительно следующими уполномоченными органами:"},{"n":"1","text":"Первой оперативно-следственной службой Федеральной службы безопасности (Управление «М») — в порядке, установленном уголовно-процессуальным законодательством, с последующим уведомлением начальника управления Федеральной службы безопасности по Нобарской области в течение 24 часов;"},{"n":"2","text":"Органами прокуратуры Российской Федерации — в пределах полномочий, предоставленных федеральным законодательством, с обязательным уведомлением начальника управления Федеральной службы безопасности по Нобарской области в течение 24 часов;"},{"n":"3","text":"Следственным комитетом Российской Федерации — по уголовным делам, отнесённым к подследственности Следственного комитета, с обязательным уведомлением начальника управления Федеральной службы безопасности по Нобарской области в течение 24 часов."},{"n":"36.3","text":"В неотложных случаях, когда промедление может привести к совершению тяжкого или особо тяжкого преступления, либо к уничтожению доказательств, либо к сокрытию подозреваемого, задержание сотрудника Федеральной службы безопасности может быть произведено сотрудниками органов внутренних дел (полиции) с немедленной (не позднее 3 часов с момента задержания) передачей задержанного в распоряжение Первой оперативно-следственной службы Федеральной службы безопасности (Управление «М») или органов прокуратуры. При этом сотрудники полиции не вправе производить допрос, обыск или иные следственные действия в отношении задержанного сотрудника ФСБ — их обязанность ограничивается физическим задержанием и обеспечением сохранности вещей и документов до прибытия уполномоченных органов."},{"n":"36.4","text":"При задержании сотрудника Федеральной службы безопасности в порядке, предусмотренном частью 3 настоящей статьи, сотрудники органов внутренних дел (полиции) обязаны:"},{"n":"•","text":"составить рапорт о задержании;"},{"n":"•","text":"зафиксировать номер жетона (при его наличии) или данные служебного удостоверения;"},{"n":"•","text":"в течение 3 часов передать задержанного и все собранные материалы в Первую оперативно-следственную службу ФСБ (Управление «М») либо прокурору;"},{"n":"•","text":"не применять к задержанному физическую силу, специальные средства или оружие, за исключением случаев необходимой обороны или пресечения нападения, угрожающего жизни и здоровью сотрудников полиции или третьих лиц."},{"n":"36.5","text":"Любые процессуальные действия уголовного характера, предусмотренные законом в отношении сотрудника Федеральной службы безопасности, произведённые органами внутренних дел (полицией), войсками национальной гвардии или иными структурами, не имеющими на то полномочий, признаются недействительными, а полученные в ходе таких действий доказательства — не имеющими юридической силы."},{"n":"36.6","text":"Сотрудники органов внутренних дел (полиции), войск национальной гвардии и иных государственных органов, осуществившие задержание сотрудника Федеральной службы безопасности с нарушением порядка, установленного настоящей статьёй, подлежат привлечению к дисциплинарной ответственности вплоть до увольнения со службы, а при наличии признаков состава преступления — к уголовной ответственности в порядке, установленном законодательством."},{"n":"36.7","text":"Положения настоящей статьи не распространяются на случаи задержания сотрудника Федеральной службы безопасности при совершении им преступления на месте преступления (в том числе террористического акта, вооружённого нападения, похищения человека, захвата заложников), если имеются достаточные данные полагать, что промедление создаёт непосредственную угрозу жизни и здоровью граждан. В указанных случаях задержание осуществляется любыми сотрудниками правоохранительных органов с обязательной передачей задержанного в органы ФСБ или прокуратуры в течение 3 часов."}]},{"n":"Статья 37","title":"Реестр жетонов сотрудников Федеральной службы безопасности","sub":[{"n":"37.1","text":"Управление Федеральной службы безопасности по Нобарской области ведёт единый реестр жетонов сотрудников, допущенных к режиму «засекреченный» (конспиративный)."},{"n":"37.2","text":"Выдача жетона производится исключительно на основании приказа начальника управления Федеральной службы безопасности по Нобарской области."},{"n":"37.3","text":"В случае утраты жетона сотрудник обязан немедленно доложить руководству. Утерянный жетон подлежит блокировке, а его номер публикуется во внутреннем циркуляре для всех правоохранительных и контролирующих органов в течение 24 часов с момента поступления доклада."},{"n":"37.4","text":"Жетон сотрудника органов Федеральной службы безопасности должен иметь следующие характеристики:"},{"n":"•","text":"Индивидуальный номер жетона в формате №XXX-YY, где XXX — три арабские цифры, YY — две буквы русского или латинского алфавита"},{"n":"•","text":"Принадлежность к структурной службе Федеральной службы безопасности (в соответствии со статьёй 17 настоящего Федерального закона) с указанием буквенного кода службы (“А”,”О”,”М”,”К”,”АПС”)"},{"n":"•","text":"Личный позывной сотрудника Федеральной службы безопасности"},{"n":"37.4.1","text":"Индивидуальный номер жетона должен состоять из 3 цифр и 2 букв через дефис."},{"n":"37.5","text":"Настоящим законом утвержден следующий формат жетона Федеральной службы безопасности:"},{"n":"","text":"[ ГУ ФСБ России ]"},{"n":"","text":"[ Управление “X” ]"},{"n":"","text":"[ №XXX-YY ]"},{"n":"","text":"[ Позывной ]"}]}]};
